CREATE TABLE IF NOT EXISTS allowance_transactions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), school_id UUID NOT NULL REFERENCES schools(id) ON DELETE CASCADE, student_id UUID NOT NULL REFERENCES user_profiles(id) ON DELETE CASCADE, subject_id UUID NOT NULL REFERENCES subjects(id) ON DELETE CASCADE, booking_id UUID REFERENCES session_bookings(id) ON DELETE SET NULL, week_start DATE NOT NULL, action allowance_action NOT NULL, minutes INTEGER NOT NULL, reason TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
